\set ON_ERROR_STOP on
SELECT public.qa_assert((SELECT status='approved' FROM public.guide_claims WHERE id='20000000-0000-0000-0000-000000000009') AND (SELECT status='pending' FROM public.guide_claims WHERE id='20000000-0000-0000-0000-000000000010') AND (SELECT count(*)=1 FROM public.moderation_audit WHERE target_id IN ('20000000-0000-0000-0000-000000000009','20000000-0000-0000-0000-000000000010')) AND (SELECT review_count=0 FROM public.guides WHERE id='10000000-0000-0000-0000-000000000004'),'competing sessions leave one owner, pending loser, one audit and unchanged aggregate');
